package TKSCJC;

import java.util.*;

public class elseifladder {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int color = 2;
		if (color == 1) {
			System.out.println("Color is blue");
		} else if (color == 2) {
			System.out.println("Color is red");
		} else {
			System.out.println("color is green");
		}
	}

}
